/* =====================================================================
   PORTFÓLIO — lógica principal (sem dependências)
   Módulos internos: dados → intro → navegação → render das seções →
   carrosséis (física própria) → leque → reveals → lightbox → trilho → rádio
   ===================================================================== */
(function () {
  'use strict';
  const D = window.PORTFOLIO;
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const isTouch = window.matchMedia('(hover: none)').matches;
  const get = (path) => path.split('.').reduce((o, k) => (o == null ? o : o[k]), D);

  /* ---------- 1. Textos vindos de data.js ---------- */
  $$('[data-txt]').forEach(el => { const v = get(el.dataset.txt); if (v != null) el.textContent = v; });
  document.title = `${D.pessoa.nomeCurto} ${D.pessoa.sobrenome} · ${D.pessoa.cargo}`;

  /* ---------- 2. Intro (portão → revelação) ---------- */
  const intro = {
    root: $('#intro'), gate: $('#introGate'),
    enter: $('#introEnter'), enterMuted: $('#introEnterMuted'), done: false,
  };
  const params = new URLSearchParams(location.search);

  function revealSite() {
    if (intro.done) return; intro.done = true;
    document.body.classList.remove('is-intro');
    document.body.classList.add('is-revealed');
    intro.root.classList.add('is-leaving');
    window.dispatchEvent(new CustomEvent('portfolio:revealed'));
    setTimeout(() => { intro.root.remove(); }, 1400);
  }
  function startIntro(withSound) {
    if (withSound && !reduced) playMusic(true);
    revealSite();
  }
  if (params.has('nointro') || reduced) {
    intro.root.remove(); document.body.classList.remove('is-intro'); document.body.classList.add('is-revealed'); intro.done = true;
    setTimeout(() => window.dispatchEvent(new CustomEvent('portfolio:revealed')), 50);
  } else {
    intro.enter.addEventListener('click', () => startIntro(true));
    intro.enterMuted.addEventListener('click', () => startIntro(false));
    document.addEventListener('keydown', (e) => { if (!intro.done && e.key === 'Escape') revealSite(); });
  }

  /* ---------- 3. Navegação ---------- */
  const nav = $('#nav'), burger = $('#burger'), menu = $('#menu');
  const heroTransparent = $('#heroTransparent');
  heroTransparent?.addEventListener('click', () => {
    const transparent = $('#inicio').classList.toggle('is-transparent');
    heroTransparent.setAttribute('aria-pressed', String(transparent));
    heroTransparent.textContent = transparent ? 'Mostrar fundo' : 'Fundo transparente';
  });
  const onScrollNav = () => nav.classList.toggle('is-scrolled', window.scrollY > 40);
  window.addEventListener('scroll', onScrollNav, { passive: true }); onScrollNav();
  const closeMenu = () => { menu.hidden = true; burger.setAttribute('aria-expanded', 'false'); document.body.classList.remove('is-locked'); };
  burger.addEventListener('click', () => { const open = menu.hidden; menu.hidden = !open; burger.setAttribute('aria-expanded', String(open)); document.body.classList.toggle('is-locked', open); });
  $$('a', menu).forEach(a => a.addEventListener('click', closeMenu));

  /* ---------- 4. Render das seções ---------- */
  const esc = (s) => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const galleries = Object.assign({}, window.PORTFOLIO_GALLERIES); // id -> {title, items:[{src, cap}]}; outros módulos (omega.js) registram as suas

  // 4a. leque de capas
  const fan = $('#deckFan');
  const n = D.capas.length; const spread = 9.5; // graus entre cards (pivô a 300% da altura → sobreposição de ~1/3)
  fan.innerHTML = D.capas.map((c, i) => {
    const a = (i - (n - 1) / 2) * spread;
    return `<button class="card" role="listitem" style="--i:${i};--a:${a.toFixed(2)}deg;z-index:${i}" data-target="${esc(c.alvo)}" aria-label="${esc(c.titulo)}, ${esc(c.categoria)}">
      <img src="${c.img}" alt="" loading="lazy" width="900" height="1200">
      <span class="card__top mono"><span class="card__cat">${esc(c.categoria)}</span><span>0${i + 1}</span></span>
      <span class="card__title">${esc(c.titulo)}<span class="card__go">Ver projeto →</span></span>
    </button>`;
  }).join('');
  fan.addEventListener('click', (e) => { const b = e.target.closest('.card'); if (!b) return; const t = $(b.dataset.target); if (t) t.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' }); });

  // 4b. websites → categorias → linhas com carrossel
  const works = $('#worksList');
  $('#projectLegend').innerHTML = D.categorias.map(cat => `<div class="project-legend__item"><img src="${esc(cat.marca)}" alt="" width="70" height="70"><div><span class="project-legend__label mono">Categoria</span><strong>${esc(cat.nome)}</strong><p>${esc(cat.descricao)}</p></div></div>`).join('');
  let rowIndex = 0; let html = '';
  D.categorias.forEach(cat => {
    const list = D.websites.filter(w => w.categoria === cat.id); if (!list.length) return;
    const marca = cat.marca ? `<img class="work-cat__mark work-cat__mark--${esc(cat.id)}" src="${esc(cat.marca)}" alt="${esc(cat.marcaAlt || '')}">` : '';
    html += `<div class="work-cat" data-reveal><div class="work-cat__head">${marca}<h3 class="work-cat__name">${esc(cat.nome)} <span class="work-cat__count mono">${String(list.length).padStart(2, '0')}</span></h3><p class="work-cat__desc">${esc(cat.descricao)}</p></div>`;
    list.forEach(w => {
      const dir = rowIndex % 2 === 0 ? 'left' : 'right'; rowIndex++;
      const prints = Array.from({ length: w.prints }, (_, k) => ({ src: `assets/img/works/${w.slug}/${k + 1}-1600.webp`, thumb: `assets/img/works/${w.slug}/${k + 1}-840.webp`, cap: w.legendas?.[k] || `Print ${k + 1}` }));
      galleries['work-' + w.slug] = { title: w.nome, items: prints.map(p => ({ src: p.src, cap: p.cap })) };
      const shots = prints.map((p, k) => `<figure class="shot" data-gal="work-${w.slug}" data-i="${k}"><img src="${p.thumb}" alt="${esc(w.nome)}, ${esc(p.cap)}" loading="lazy" width="840" height="472"><figcaption class="shot__n">${String(k + 1).padStart(2, '0')} / ${String(w.prints).padStart(2, '0')}</figcaption></figure>`).join('');
      html += `<article class="work-row ${dir === 'right' ? 'work-row--rtl' : ''}" id="work-${w.slug}" data-reveal>
        <div class="work-info">
          <p class="work-info__index mono"><b>${String(rowIndex).padStart(2, '0')}</b><span class="work-info__cat">${esc(cat.nome)}</span></p>
          <h4 class="work-info__name">${esc(w.nome)}</h4>
          <p class="work-info__sub">${esc(w.subtitulo)}</p>
          <p class="work-info__desc">${esc(w.descricao)}</p>
          <ul class="work-info__tags">${w.tags.map(t => `<li>${esc(t)}</li>`).join('')}</ul>
          <div class="work-info__ctrl">
            <button class="ctrl-btn" type="button" data-nudge="-1" aria-label="Anterior">←</button>
            <button class="ctrl-btn" type="button" data-nudge="1" aria-label="Próximo">→</button>
            <button class="work-info__view mono" type="button" data-open="work-${w.slug}">Ver prints ampliados</button>
          </div>
        </div>
        <div class="strip" data-dir="${dir}"><div class="strip__track">${shots}</div></div>
      </article>`;
    });
    html += `</div>`;
  });
  works.innerHTML = html;

  // 4c. sistemas
  const sys = D.sistemas;
  $('#systemsList').innerHTML = sys.itens.map((s, i) => {
    galleries['sys-' + s.slug] = { title: s.titulo, items: s.abas ? s.abas.map(a => ({ src: a.full, cap: 'aba ' + a.nome })) : [{ src: s.full, cap: 'tela completa' }] };
    return `<article class="sys" data-reveal style="--d:${i * 60}ms">
      <div class="sys__thumb" data-gal="sys-${s.slug}" data-i="0" role="button" tabindex="0" aria-label="Ampliar: ${esc(s.titulo)}">
        <div class="bgimg" style="background-image:url('${s.thumb}')" aria-hidden="true"></div>
        <img class="main" src="${s.thumb}" alt="${esc(s.titulo)}">
        ${s.thumbAlt ? `<img class="alt" src="${s.thumbAlt}" alt="" aria-hidden="true">` : ''}
        <span class="sys__open mono">Abrir ↗</span>
        <span class="sys__badge">${esc(s.badge)}</span>
      </div>
      <div class="sys__body">
        <h3 class="sys__title">${esc(s.titulo)}</h3>
        <ul class="sys__meta mono">${s.meta.map(m => `<li>${esc(m)}</li>`).join('')}</ul>
        <div class="sys__channel">
          <img src="${sys.canal.avatar}" alt="" width="40" height="40" loading="lazy">
          <div><b>${esc(sys.canal.nome)} <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l2.4 2.1 3.1-.5 1 3 2.9 1.3-.6 3.1 2 2.5-2 2.5.6 3.1-2.9 1.3-1 3-3.1-.5L12 22l-2.4-2.1-3.1.5-1-3-2.9-1.3.6-3.1-2-2.5 2-2.5-.6-3.1 2.9-1.3 1-3 3.1.5z M10.4 15.6l-3-3 1.4-1.4 1.6 1.6 4.8-4.8 1.4 1.4z"/></svg></b><small>${esc(sys.canal.papel)}</small></div>
        </div>
        <p class="sys__desc">${esc(s.descricao)}</p>
        ${s.abas ? `<ul class="sys__abas" aria-label="Abas da planilha">${s.abas.map((a, k) => `<li><button type="button" data-gal="sys-${s.slug}" data-i="${k}" aria-label="Ampliar aba ${esc(a.nome)}"><img src="${a.thumb}" alt="" loading="lazy"><span class="mono">${esc(a.nome)}</span></button></li>`).join('')}</ul>` : ''}
        <div class="sys__actions">
          <button class="sys__link mono" type="button" data-open="sys-${s.slug}">Ver em tela cheia</button>
          ${s.arquivo ? `<a class="sys__download mono" href="${s.arquivo}" download><svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M10 3v9m0 0-3.5-3.5M10 12l3.5-3.5M4 14.5v1a1.5 1.5 0 0 0 1.5 1.5h9a1.5 1.5 0 0 0 1.5-1.5v-1" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>Baixar planilha</a>` : ''}
        </div>
        ${s.arquivoNota ? `<p class="sys__filenote mono">🔒 ${esc(s.arquivoNota)}</p>` : ''}
      </div>
    </article>`;
  }).join('');

  // 4d. sobre, qualificações, habilidades, contato
  $('#aboutText').innerHTML = D.sobre.paragrafos.map((p, i) => `<p data-reveal style="--d:${i * 90}ms">${esc(p)}</p>`).join('');
  $('#qualsList').innerHTML = D.sobre.qualificacoes.map((q, i) => `<li data-reveal style="--d:${i * 60}ms"><span class="quals__n">0${i + 1}</span><span class="quals__t">${esc(q.titulo)}</span><span class="quals__d">${esc(q.detalhe)}</span></li>`).join('');
  $('#educationList').innerHTML = D.sobre.formacoes.map((f, i) => `<li data-reveal style="--d:${i * 60}ms"><span class="quals__n">0${i + 1}</span><span class="quals__t">${esc(f.titulo)}</span><span class="quals__d">${esc(f.detalhe)}</span></li>`).join('');
  $('#skillList').innerHTML = D.habilidades.lista.map((s, i) => `<li class="skill" data-reveal style="--d:${i * 70}ms;--c:${s.cor}"><img class="skill__logo" src="${s.logo}" alt="" width="60" height="60" loading="lazy"><div><h4 class="skill__name">${esc(s.nome)}</h4>${s.detalhe ? `<p class="skill__detail">${esc(s.detalhe)}</p>` : ''}${s.ferramentas && s.ferramentas.length ? `<ul class="skill__tools" aria-label="Ferramentas">${s.ferramentas.map(f => `<li>${esc(f)}</li>`).join('')}</ul>` : ''}</div><span class="skill__level">${esc(s.nivel)}</span></li>`).join('');
  const mail = $('#contactMail'); mail.href = 'mailto:' + D.pessoa.email; mail.textContent = D.pessoa.email;
  const ideaForm = $('#ideaForm');
  ideaForm?.addEventListener('submit', (event) => {
    event.preventDefault();
    const idea = $('#ideaMessage').value.trim();
    if (!idea || !D.pessoa.whatsapp) return;
    // recursos marcados com "+ Quero isso" na seção Possibilidades (se ainda não estiverem no texto)
    const picks = typeof window.PORTFOLIO_PICKS === 'function' ? window.PORTFOLIO_PICKS() : [];
    const extra = picks.length && !idea.includes(D.possibilidades.cta.prefixo) ? `\n\nRecursos que me interessam: ${picks.join(', ')}.` : '';
    const message = `Olá, Gabriel! Tenho uma ideia de projeto:\n\n${idea}${extra}`;
    window.open(`https://wa.me/${D.pessoa.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`, '_blank', 'noopener');
  });
  const links = [`<li><a href="mailto:${esc(D.pessoa.email)}"><img src="data:image/jpeg;base64," alt="" width="64" height="64"><span>E-mail</span></a></li>`];
  if (D.pessoa.whatsapp) links.push(`<li><a href="https://wa.me/${D.pessoa.whatsapp.replace(/\D/g, '')}" target="_blank" rel="noopener"><img src="data:image/jpeg;base64," alt="" width="64" height="64"><span>WhatsApp</span></a></li>`);
  if (D.pessoa.instagram) links.push(`<li><a href="https://instagram.com/${esc(D.pessoa.instagram.replace('@', ''))}" target="_blank" rel="noopener"><img src="data:image/jpeg;base64," alt="" width="64" height="64"><span>Instagram</span></a></li>`);
  if (D.pessoa.linkedin) links.push(`<li><a href="${esc(D.pessoa.linkedin)}" target="_blank" rel="noopener">LinkedIn ↗</a></li>`);
  if (D.pessoa.github) links.push(`<li><a href="${esc(D.pessoa.github)}" target="_blank" rel="noopener">GitHub ↗</a></li>`);
  links.push(`<li>${esc(D.pessoa.cidade)}</li>`);
  $('#contactLinks').innerHTML = links.join('');

  /* ---------- 5. Carrosséis com física própria ---------- */
  class Strip {
    constructor(el) {
      this.el = el; this.track = $('.strip__track', el); this.dir = el.dataset.dir === 'right' ? 1 : -1;
      this.x = 0; this.v = 0; this.base = reduced ? 0 : 38; // px/s
      this.hover = false; this.drag = null; this.visible = false; this.setWidth = 0; this.last = 0; this.nudgeV = 0;
      this.fill(); this.bind();
    }
    fill() {
      const items = Array.from(this.track.children); this.originals = items.length;
      const measure = () => items.reduce((a, c) => a + c.getBoundingClientRect().width, 0) + 16 * items.length;
      this.setWidth = measure();
      const need = Math.max(2, Math.ceil(this.el.clientWidth / Math.max(1, this.setWidth)) + 1);
      for (let c = 1; c < need; c++) items.forEach(it => { const k = it.cloneNode(true); k.setAttribute('aria-hidden', 'true'); this.track.appendChild(k); });
      this.copies = need;
      if (this.dir === 1) this.x = -this.setWidth + 1; // começa no fim de um conjunto para deslizar à direita sem lacuna
    }
    bind() {
      this.el.addEventListener('pointerenter', () => { this.hover = true; });
      this.el.addEventListener('pointerleave', () => { this.hover = false; });
      this.el.addEventListener('pointerdown', (e) => { if (e.button !== 0) return; this.drag = { x0: e.clientX, x: e.clientX, t: performance.now(), moved: false, startX: this.x }; this.el.setPointerCapture(e.pointerId); });
      this.el.addEventListener('pointermove', (e) => { if (!this.drag) return; const dx = e.clientX - this.drag.x0; if (Math.abs(dx) > 4) { this.drag.moved = true; this.el.classList.add('is-dragging'); } const now = performance.now(); const dt = Math.max(1, now - this.drag.t); this.v = (e.clientX - this.drag.x) / dt * 1000; this.drag.x = e.clientX; this.drag.t = now; this.x = this.drag.startX + dx; });
      const end = (e) => { if (!this.drag) return; const moved = this.drag.moved; this.drag = null; this.el.classList.remove('is-dragging'); if (moved) { this.suppressClick = true; setTimeout(() => this.suppressClick = false, 50); } };
      this.el.addEventListener('pointerup', end); this.el.addEventListener('pointercancel', end);
      this.el.addEventListener('click', (e) => { if (this.suppressClick) { e.stopPropagation(); e.preventDefault(); } }, true);
      const io = new IntersectionObserver(([en]) => { this.visible = en.isIntersecting; }, { rootMargin: '120px 0px' }); io.observe(this.el);
    }
    nudge(dirSign) { const step = ($('.shot', this.track).getBoundingClientRect().width + 16); this.nudgeV += -dirSign * step * 4.2; }
    tick(dt) {
      if (!this.visible) return;
      if (!this.drag) {
        const target = this.hover || isTouch && this.v !== 0 ? this.base * 0.18 : this.base;
        // deslocamento automático + inércia do arrasto + impulso das setas
        this.v += (0 - this.v) * Math.min(1, dt * 4.5);
        this.nudgeV += (0 - this.nudgeV) * Math.min(1, dt * 6);
        this.x += (this.dir * target + this.v + this.nudgeV) * dt;
      }
      // laço infinito
      if (this.x <= -this.setWidth) this.x += this.setWidth; else if (this.x > 0) this.x -= this.setWidth;
      this.track.style.transform = `translate3d(${this.x.toFixed(2)}px,0,0)`;
    }
  }
  const strips = $$('.strip').map(el => new Strip(el));
  $$('[data-nudge]').forEach(b => b.addEventListener('click', () => { const s = strips.find(s => s.el.closest('.work-row') === b.closest('.work-row')); if (s) s.nudge(+b.dataset.nudge); }));
  let last = performance.now();
  (function loop(now) { const dt = Math.min(0.05, (now - last) / 1000); last = now; strips.forEach(s => s.tick(dt)); requestAnimationFrame(loop); })(last);
  window.addEventListener('resize', () => { strips.forEach(s => { const items = Array.from(s.track.children).slice(0, s.originals); s.setWidth = items.reduce((a, c) => a + c.getBoundingClientRect().width, 0) + 16 * items.length; }); });

  /* ---------- 6. Reveals + leque ---------- */
  const io = new IntersectionObserver((entries) => entries.forEach(en => { if (en.isIntersecting) { en.target.classList.add('is-in'); io.unobserve(en.target); } }), { threshold: 0.12, rootMargin: '0px 0px -6% 0px' });
  $$('[data-reveal]').forEach(el => io.observe(el));
  const deck = $('#trabalho'); const ioDeck = new IntersectionObserver(([en]) => { if (en.isIntersecting) { deck.classList.add('is-in'); ioDeck.disconnect(); } }, { threshold: 0.25 }); ioDeck.observe(deck);

  // em telas pequenas o mascote só aparece no início e no contato; no desktop some nas áreas densas (websites/sistemas)
  const mascotShouldHide = (id) => window.matchMedia('(max-width: 900px)').matches ? !(id === 'inicio' || id === 'contato') : (id === 'websites' || id === 'sistemas' || id === 'sobre');

  /* ---------- 7. Lightbox ---------- */
  const lb = { root: $('#lightbox'), img: $('#lbImg'), title: $('#lbTitle'), count: $('#lbCount'), gal: null, i: 0, lastFocus: null };
  function lbShow() { const g = galleries[lb.gal]; const it = g.items[lb.i]; lb.img.src = it.src; lb.img.alt = `${g.title}, ${it.cap}`; lb.title.textContent = `${g.title} · ${it.cap}`; lb.count.textContent = `${lb.i + 1} / ${g.items.length}`; $('#lbPrev').style.visibility = $('#lbNext').style.visibility = g.items.length > 1 ? 'visible' : 'hidden'; }
  function lbOpen(gal, i) { if (!galleries[gal]) return; lb.gal = gal; lb.i = i; lb.lastFocus = document.activeElement; lb.root.hidden = false; document.body.classList.add('is-locked'); $('#mascot').classList.add('is-hidden'); lbShow(); $('#lbClose').focus(); }
  function lbClose() { lb.root.hidden = true; document.body.classList.remove('is-locked'); $('#mascot').classList.toggle('is-hidden', mascotShouldHide(current)); lb.img.src = ''; if (lb.lastFocus) lb.lastFocus.focus(); }
  function lbStep(d) { const g = galleries[lb.gal]; lb.i = (lb.i + d + g.items.length) % g.items.length; lbShow(); }
  document.addEventListener('click', (e) => {
    const t = e.target.closest('[data-gal]'); if (t) { lbOpen(t.dataset.gal, +t.dataset.i || 0); return; }
    const o = e.target.closest('[data-open]'); if (o) { lbOpen(o.dataset.open, 0); }
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && e.target.matches('[data-gal]')) { lbOpen(e.target.dataset.gal, 0); return; }
    if (lb.root.hidden) return;
    if (e.key === 'Escape') lbClose(); else if (e.key === 'ArrowRight') lbStep(1); else if (e.key === 'ArrowLeft') lbStep(-1);
  });
  $('#lbClose').addEventListener('click', lbClose); $('#lbPrev').addEventListener('click', () => lbStep(-1)); $('#lbNext').addEventListener('click', () => lbStep(1));
  lb.root.addEventListener('click', (e) => { if (e.target === lb.root) lbClose(); });

  /* ---------- 8. Trilho do túnel + link ativo ---------- */
  const sections = $$('[data-rail]'); const rail = $('#rail'); const car = $('.rail__car', rail);
  rail.insertAdjacentHTML('beforeend', sections.map((s, i) => `<span class="rail__tick" data-label="${esc(s.dataset.rail)}" data-target="#${s.id}" style="top:${(i / (sections.length - 1)) * 100}%"></span>`).join(''));
  rail.setAttribute('aria-hidden', 'false');
  rail.addEventListener('click', (e) => { const t = e.target.closest('.rail__tick'); if (t) $(t.dataset.target).scrollIntoView({ behavior: reduced ? 'auto' : 'smooth' }); });
  const navLinks = $$('.nav__links a'); const ticks = $$('.rail__tick', rail);
  let current = '';
  function updateRail() {
    const y = window.scrollY + window.innerHeight * 0.42; let idx = 0;
    sections.forEach((s, i) => { if (s.offsetTop <= y) idx = i; });
    const id = sections[idx].id;
    if (id !== current) { current = id; navLinks.forEach(a => a.classList.toggle('is-active', a.dataset.sec === id)); ticks.forEach((t, i) => t.classList.toggle('is-active', i === idx));
      // o mascote sai de cena nas áreas densas de conteúdo (websites e sistemas) para não cobrir os projetos
      if (lb.root.hidden) $('#mascot').classList.toggle('is-hidden', mascotShouldHide(id)); }
    const max = document.documentElement.scrollHeight - window.innerHeight; const p = max > 0 ? Math.min(1, window.scrollY / max) : 0;
    car.style.top = (p * 100) + '%';
  }
  window.addEventListener('scroll', updateRail, { passive: true }); window.addEventListener('resize', updateRail); updateRail();

  /* ---------- 9. Música (toca uma vez na entrada; depois só pelo botão do topo) ---------- */
  const music = $('#music'); const soundBtn = $('#soundToggle'); const mascotEl = $('#mascot'); const tip = $('#mascotTip');
  let playing = false; let fadeTimer = null;
  function setState(on) {
    playing = on; soundBtn.setAttribute('aria-pressed', String(on)); soundBtn.setAttribute('aria-label', on ? 'Pausar música' : 'Tocar música');
    tip.textContent = on ? 'Música tocando. Toque para pausar' : 'Toque para tocar a música';
    mascotEl.classList.add('is-talking'); clearTimeout(setState._t); setState._t = setTimeout(() => mascotEl.classList.remove('is-talking'), 1800);
    window.dispatchEvent(new CustomEvent('portfolio:music', { detail: { on } }));
  }
  function fadeTo(target, ms) { clearInterval(fadeTimer); const from = music.volume; const t0 = performance.now(); fadeTimer = setInterval(() => { const k = Math.min(1, (performance.now() - t0) / ms); music.volume = from + (target - from) * k; if (k >= 1) clearInterval(fadeTimer); }, 40); }
  function playMusic(fromStart) {
    if (fromStart || music.ended) music.currentTime = 0;
    try { music.volume = fromStart ? 0 : music.volume || 0.5; } catch (e) { /* iOS ignora volume */ }
    const p = music.play();
    if (p && p.catch) p.catch(() => setState(false));
    if (fromStart) fadeTo(0.5, 900);
    setState(true);
  }
  function pauseMusic() { music.pause(); setState(false); }
  function toggleMusic() { if (playing) pauseMusic(); else playMusic(false); }
  music.addEventListener('ended', () => setState(false));
  soundBtn.addEventListener('click', toggleMusic);
  document.addEventListener('visibilitychange', () => { if (document.hidden && playing) music.pause(); else if (!document.hidden && playing) music.play().catch(() => {}); });

  /* ---------- 10. Parallax leve do hero ---------- */
  const hero = $('#inicio');
  if (!isTouch && !reduced) {
    let tx = 0, ty = 0, cx = 0, cy = 0;
    window.addEventListener('pointermove', (e) => { tx = (e.clientX / window.innerWidth - 0.5) * 18; ty = (e.clientY / window.innerHeight - 0.5) * 12; }, { passive: true });
    (function par() { cx += (tx - cx) * 0.06; cy += (ty - cy) * 0.06; hero.style.setProperty('--px', cx.toFixed(2) + 'px'); hero.style.setProperty('--py', cy.toFixed(2) + 'px'); requestAnimationFrame(par); })();
  }

  /* ---------- API para os módulos 3D ---------- */
  window.PortfolioUI = { toggleMusic, isPlaying: () => playing, reduced, isTouch };
})();
